DROP TABLE IF EXISTS `diagnosis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `diagnosis` (
  `DIAGNOSIS_ID` bigint NOT NULL,
  `Age_Range` varchar(255) DEFAULT NULL,
  `Asterisk` varchar(255) DEFAULT NULL,
  `Comment` varchar(255) DEFAULT NULL,
  `Dagger` varchar(255) DEFAULT NULL,
  `End_Date` date DEFAULT NULL,
  `Gender` varchar(255) DEFAULT NULL,
  `ICD10_Code` varchar(255) DEFAULT NULL,
  `ICD_3Code_Desc` varchar(255) DEFAULT NULL,
  `Sequelae` varchar(255) DEFAULT NULL,
  `Start_Date` date DEFAULT NULL,
  `Status_ADM` varchar(255) DEFAULT NULL,
  `Valid_ICD10_ClinicalUse` varchar(255) DEFAULT NULL,
  `Valid_ICD10_Primary` varchar(255) DEFAULT NULL,
  `WHO_FULL_Desc` varchar(255) DEFAULT NULL,
  `chapterNo` varchar(255) DEFAULT NULL,
  `chapter_Desc` varchar(255) DEFAULT NULL,
  `diagID` varchar(255) DEFAULT NULL,
  `group_Code` varchar(255) DEFAULT NULL,
  `group_Description` varchar(255) DEFAULT NULL,
  `iCD_3Code` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`DIAGNOSIS_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

